# Fixed pilot release. Verifies the ZIP SHA256 before executing its installer.
# No Wiki data is downloaded or uploaded. Does not change execution policy.
$ErrorActionPreference='Stop'; if (@(Get-ExecutionPolicy -List | Where-Object {$_.ExecutionPolicy -in @('AllSigned','Restricted')}).Count) {throw 'IT signing policy restricts this installer'}; [Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12; $jjDir=Join-Path $env:TEMP ('jjaitech-install-'+[guid]::NewGuid().ToString('N')); New-Item -ItemType Directory -Path $jjDir | Out-Null; $jjZip=Join-Path $jjDir 'release.zip'; Invoke-WebRequest -UseBasicParsing -Uri 'https://github.com/JachinLan/jjaitech-memory/releases/download/v1.2.0-rc.2-online.1/jjaitech-memory-windows-1.2.0-rc.2-online.1.zip' -OutFile $jjZip -TimeoutSec 120; if ((Get-FileHash -Algorithm SHA256 -LiteralPath $jjZip).Hash.ToLowerInvariant() -ne 'e40377631d9b68aa89dc18230c947395f3cb8f41b30bf830fa328b0a75846d51') {throw 'Download checksum mismatch; installation stopped'}; Expand-Archive -LiteralPath $jjZip -DestinationPath $jjDir; & ([scriptblock]::Create([IO.File]::ReadAllText((Join-Path $jjDir 'jjaitech-memory/distribution/bootstrap-windows.ps1')))) -PackageRoot $jjDir
